using System.Text.RegularExpressions;

namespace QuickBuilder.Shared.Infrastructure.Storage;

/// <summary>
/// The name of one stored object (003 contracts/storage-provider.md §2).
/// </summary>
/// <remarks>
/// The grammar is the security boundary: 1 to 8 segments of <c>[a-z0-9-]{1,64}</c> joined by
/// <c>/</c>. That rules out <c>..</c>, separators, drive letters, encoded characters and
/// anything a user typed, whatever arrives in a request (FR-021). Keys are generated by the
/// system; a key that breaks the grammar is a bug, so construction throws rather than
/// returning a result.
/// </remarks>
public readonly partial record struct StorageKey
{
    /// <summary>The most segments a key may have.</summary>
    public const int MaxSegments = 8;

    /// <summary>The longest a single segment may be.</summary>
    public const int MaxSegmentLength = 64;

    public StorageKey(string value)
    {
        ArgumentNullException.ThrowIfNull(value);

        var problem = Check(value);
        if (problem is not null)
        {
            throw new ArgumentException($"'{value}' is not a valid storage key: {problem}", nameof(value));
        }

        Value = value;
    }

    public string Value { get; }

    /// <summary>The first segment. For module keys this is the owning site's id (Principle V).</summary>
    public string FirstSegment => Value.Split('/', 2)[0];

    /// <summary>How many segments the key has.</summary>
    public int SegmentCount => Value.Count(c => c == '/') + 1;

    public static StorageKey Parse(string value) => new(value);

    /// <summary>True when <paramref name="value"/> satisfies the grammar.</summary>
    public static bool IsValid(string? value) => value is not null && Check(value) is null;

    /// <summary>True when the key begins with <paramref name="prefix"/>, compared ordinally.</summary>
    public bool StartsWith(string prefix)
    {
        ArgumentNullException.ThrowIfNull(prefix);
        return Value.StartsWith(prefix, StringComparison.Ordinal);
    }

    /// <summary>
    /// Whether <paramref name="prefix"/> may be passed to <c>ListAsync</c>: empty, or whole
    /// segments followed by at most one partial segment. Never anything a key could not start with.
    /// </summary>
    public static bool IsValidPrefix(string? prefix) =>
        prefix is not null && (prefix.Length == 0 || PrefixPattern().IsMatch(prefix));

    public override string ToString() => Value;

    private static string? Check(string value)
    {
        if (value.Length == 0)
        {
            return "it is empty.";
        }

        var segments = value.Split('/');
        if (segments.Length > MaxSegments)
        {
            return $"it has {segments.Length} segments; at most {MaxSegments} are allowed.";
        }

        foreach (var segment in segments)
        {
            if (segment.Length == 0)
            {
                return "it has an empty segment (a leading, trailing or doubled '/').";
            }

            if (segment.Length > MaxSegmentLength)
            {
                return $"a segment is {segment.Length} characters long; at most {MaxSegmentLength} are allowed.";
            }

            if (!SegmentPattern().IsMatch(segment))
            {
                return "segments may contain only lower-case letters, digits and '-'.";
            }
        }

        return null;
    }

    [GeneratedRegex("^[a-z0-9-]+$", RegexOptions.CultureInvariant)]
    private static partial Regex SegmentPattern();

    [GeneratedRegex("^([a-z0-9-]{1,64}/){0,7}[a-z0-9-]{0,64}$", RegexOptions.CultureInvariant)]
    private static partial Regex PrefixPattern();
}
